// Nova Bots tenants — one isolated engine per account.
//
// A tenant is one account's own engine: its own container, its own volumes
// (DSH_HOME at /data and the Bots' /workspace), its own launch token and cookie
// key (both generated by the engine inside the tenant's own volume), its own
// loopback port, and no provider key unless the account brings one or the
// operator assigns one to that tenant alone.
//
// The trust boundary is the container. A tenant has full access INSIDE its
// container (that is the product), so everything here assumes the tenant's
// engine process is hostile to every other tenant:
//
//   * no docker socket, no host folder, no host-gateway alias, no shared volume;
//   * --cap-drop ALL plus the four capabilities the entrypoint needs to hand
//     the volume to the node user and drop to it (CHOWN, SETUID, SETGID,
//     DAC_OVERRIDE), --security-opt no-new-privileges (which also disables
//     sudo), BOT_ROOT=0;
//   * cpu, memory (no swap), pids and log-size limits;
//   * one user-defined bridge for all tenants with inter-container traffic
//     disabled (enable_icc=false): a tenant cannot reach another tenant's
//     engine, and the published port is bound to 127.0.0.1 only;
//   * nothing the portal forwards carries a secret (bridge.mjs).
//
// The account that owned the workspace before tenancy (the admin) keeps the
// existing shared engine as ITS tenant ('legacy' kind): it is mapped, never
// recreated, stopped or deleted by the provisioner.

import { execFile } from 'node:child_process'
import { createCipheriv, createDecipheriv, createHash, randomBytes } from 'node:crypto'
import { mkdtemp, rm, writeFile } from 'node:fs/promises'
import { createServer } from 'node:net'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

const number = (value, fallback) => {
  const parsed = Number(value)
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback
}

const csv = (value) => String(value ?? '').split(',').map(item => item.trim()).filter(Boolean)

const NAME = /^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,127}$/
const assertName = (value, what) => {
  if (!NAME.test(String(value))) throw new Error(`invalid ${what}: ${value}`)
  return value
}

export const tenancyConfigFromEnv = (env = process.env) => ({
  instance: env.NOVA_TENANT_INSTANCE ?? 'production',
  image: env.NOVA_TENANT_IMAGE ?? 'nova-bots:local',
  prefix: env.NOVA_TENANT_PREFIX ?? 'nova-bots-t-',
  network: env.NOVA_TENANT_NETWORK ?? 'nova-bots-tenants',
  bridgeName: env.NOVA_TENANT_BRIDGE_NAME ?? 'nb-tenants',
  bindHost: env.NOVA_TENANT_BIND ?? '127.0.0.1',
  portBase: number(env.NOVA_TENANT_PORT_BASE, 14100),
  portCount: number(env.NOVA_TENANT_PORT_COUNT, 200),
  limits: {
    cpus: String(env.NOVA_TENANT_CPUS ?? '1.0'),
    memory: String(env.NOVA_TENANT_MEMORY ?? '1536m'),
    pids: number(env.NOVA_TENANT_PIDS, 512),
  },
  logMaxSize: env.NOVA_TENANT_LOG_MAX_SIZE ?? '10m',
  logMaxFiles: number(env.NOVA_TENANT_LOG_MAX_FILES, 3),
  restartPolicy: env.NOVA_TENANT_RESTART ?? 'on-failure:5',
  idleMinutes: number(env.NOVA_TENANT_IDLE_MINUTES, 30),
  reapIntervalMs: number(env.NOVA_TENANT_REAP_INTERVAL_MS, 60000),
  maxRunning: number(env.NOVA_TENANT_MAX_RUNNING, 12),
  maxTotal: number(env.NOVA_TENANT_MAX_TOTAL, 150),
  startTimeoutMs: number(env.NOVA_TENANT_START_TIMEOUT_MS, 120000),
  trustedHosts: csv(env.NOVA_TENANT_TRUSTED_HOST ?? 'localhost,127.0.0.1,bots.alilabsx.com'),
  // Provider key env names the operator may assign to a tenant.
  keyEnvs: csv(env.NOVA_TENANT_KEY_ENVS ?? 'DEEPSEEK_API_KEY,DEEPSEEK_BASE_URL,MINIMAX_API_KEY,FIREWORKS_API_KEY'),
  secretKey: env.NOVA_TENANT_SECRET_KEY ?? '',
  exportDir: env.NOVA_TENANT_EXPORT_DIR ?? '',
  // The pre-tenancy engine, kept as its owner's tenant.
  legacyEmail: (env.NOVA_LEGACY_TENANT_EMAIL ?? '').trim().toLowerCase(),
  legacyContainer: env.NOVA_ENGINE_CONTAINER ?? 'nova-bots',
  legacyUrl: env.NOVA_ENGINE_URL ?? 'http://127.0.0.1:13083',
  docker: env.NOVA_DOCKER_BIN ?? 'docker',
})

// ---- per-tenant secrets ----------------------------------------------------

// AES-256-GCM with a key derived from NOVA_TENANT_SECRET_KEY. Without that key
// no provider key can be assigned at all (fail closed, never stored in clear).
export const secretBox = (material) => {
  if (!material || String(material).length < 32) return null
  const key = createHash('sha256').update(`nova-bots-tenant-secrets\u0000${material}`).digest()
  return {
    seal(value) {
      const iv = randomBytes(12)
      const cipher = createCipheriv('aes-256-gcm', key, iv)
      const body = Buffer.concat([cipher.update(JSON.stringify(value), 'utf8'), cipher.final()])
      return `v1.${iv.toString('base64url')}.${cipher.getAuthTag().toString('base64url')}.${body.toString('base64url')}`
    },
    open(sealed) {
      const [version, iv, tag, body] = String(sealed ?? '').split('.')
      if (version !== 'v1') throw new Error('unknown secret format')
      const decipher = createDecipheriv('aes-256-gcm', key, Buffer.from(iv, 'base64url'))
      decipher.setAuthTag(Buffer.from(tag, 'base64url'))
      return JSON.parse(Buffer.concat([decipher.update(Buffer.from(body, 'base64url')), decipher.final()]).toString('utf8'))
    },
  }
}

// ---- docker ----------------------------------------------------------------

export class DockerCli {
  constructor({ bin = 'docker' } = {}) {
    this.bin = bin
  }

  run(args, { timeout = 60000, maxBuffer = 4 * 1024 * 1024 } = {}) {
    return new Promise((resolve, reject) => {
      execFile(this.bin, args, { timeout, maxBuffer }, (error, stdout, stderr) => {
        if (error) {
          const failure = new Error(`docker ${args[0]} failed: ${String(stderr || error.message).trim().slice(0, 400)}`)
          failure.stderr = String(stderr ?? '')
          return reject(failure)
        }
        resolve(String(stdout))
      })
    })
  }

  async inspect(name) {
    try {
      const out = await this.run(['container', 'inspect', '--format', '{{json .State}}', name], { timeout: 15000 })
      const state = JSON.parse(out)
      return { exists: true, running: state.Running === true, startedAt: state.StartedAt ?? null, status: state.Status }
    } catch (error) {
      if (/no such (container|object)/i.test(error.stderr ?? error.message)) return { exists: false, running: false }
      throw error
    }
  }

  async ensureNetwork({ name, bridgeName, instance }) {
    try {
      await this.run(['network', 'inspect', name], { timeout: 15000 })
      return
    } catch (error) {
      if (!/not found|no such network/i.test(error.stderr ?? error.message)) throw error
    }
    await this.run([
      'network', 'create', '--driver', 'bridge',
      '--opt', 'com.docker.network.bridge.enable_icc=false',
      '--opt', `com.docker.network.bridge.name=${bridgeName}`,
      '--label', `nova-bots.instance=${instance}`,
      '--label', 'nova-bots.role=tenant-network',
      name,
    ])
  }

  async ensureVolume(name, labels) {
    await this.run(['volume', 'create', ...Object.entries(labels).flatMap(([k, v]) => ['--label', `${k}=${v}`]), name])
  }

  async readFile(container, path) {
    const out = await this.run(['exec', '-u', 'node', container, 'cat', path], { timeout: 15000, maxBuffer: 64 * 1024 })
    return out.trim()
  }

  async listLabelled(instance) {
    const out = await this.run(['ps', '-a', '--filter', `label=nova-bots.instance=${instance}`, '--filter', 'label=nova-bots.tenant',
      '--format', '{{.Names}}\t{{.State}}\t{{.Label "nova-bots.tenant"}}'], { timeout: 20000 })
    return out.split('\n').filter(Boolean).map(line => {
      const [name, state, tenant] = line.split('\t')
      return { name, running: state === 'running', tenant }
    })
  }

  async stats(names) {
    if (!names.length) return {}
    const out = await this.run(['stats', '--no-stream', '--format', '{{json .}}', ...names], { timeout: 30000 })
    const result = {}
    for (const line of out.split('\n').filter(Boolean)) {
      try {
        const row = JSON.parse(line)
        result[row.Name] = { cpu: row.CPUPerc, memory: row.MemUsage, memoryPercent: row.MemPerc, pids: Number(row.PIDs) }
      } catch { /* a line that is not JSON is skipped */ }
    }
    return result
  }
}

// The docker create arguments for one tenant. Pure, so the hardening is unit
// tested without docker.
export const containerArgs = ({ tenant, config, envFile }) => {
  const limits = { ...config.limits, ...(tenant.limits ?? {}) }
  const args = [
    'create',
    '--name', assertName(tenant.container, 'container name'),
    '--hostname', 'nova-bots',
    '--label', `nova-bots.instance=${config.instance}`,
    '--label', `nova-bots.tenant=${tenant.id}`,
    '--label', 'nova-bots.role=tenant-engine',
    '--network', assertName(config.network, 'network'),
    '--publish', `${config.bindHost}:${Number(tenant.port)}:3080`,
    '--cap-drop', 'ALL',
    '--cap-add', 'CHOWN', '--cap-add', 'SETUID', '--cap-add', 'SETGID', '--cap-add', 'DAC_OVERRIDE',
    '--security-opt', 'no-new-privileges',
    '--cpus', String(limits.cpus),
    '--memory', String(limits.memory),
    '--memory-swap', String(limits.memory),
    '--pids-limit', String(limits.pids),
    '--log-driver', 'json-file',
    '--log-opt', `max-size=${config.logMaxSize}`,
    '--log-opt', `max-file=${config.logMaxFiles}`,
    '--restart', config.restartPolicy,
    '--stop-timeout', '15',
    '--volume', `${assertName(tenant.volume, 'volume')}:/data`,
    '--volume', `${assertName(`${tenant.volume}-work`, 'volume')}:/workspace`,
    '--env', 'NOVA_LAUNCH_TOKEN_FILE=/data/.launch-token',
    '--env', `NOVA_TRUSTED_HOST=${config.trustedHosts.join(',')}`,
    '--env', 'BOT_ROOT=0',
    '--env', 'NOVA_HOST=0.0.0.0',
    '--env', 'NOVA_LISTEN_PORT=3080',
    '--env', 'DSH_TELEMETRY_DISABLED=1',
  ]
  if (envFile) args.push('--env-file', envFile)
  args.push(config.image)
  return args
}

const portFree = (port, host) => new Promise(resolve => {
  const server = createServer()
  server.once('error', () => resolve(false))
  server.listen(port, host, () => server.close(() => resolve(true)))
})

// ---- the store -------------------------------------------------------------

const COLUMNS = `id, user_id, kind, container, volume, port, state, limits, (provider_secret IS NOT NULL) AS has_key,
  last_error, created_at, last_active_at, started_at, stopped_at`

export class TenantStore {
  constructor(pool) {
    this.pool = pool
  }

  async migrate() {
    await this.pool.query(`
      CREATE TABLE IF NOT EXISTS tenants (
        id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
        user_id         uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE RESTRICT,
        kind            varchar(16) NOT NULL DEFAULT 'managed',
        container       varchar(128) NOT NULL UNIQUE,
        volume          varchar(128),
        port            integer UNIQUE,
        state           varchar(16) NOT NULL DEFAULT 'new',
        limits          jsonb NOT NULL DEFAULT '{}'::jsonb,
        provider_secret text,
        last_error      text,
        created_at      timestamptz NOT NULL DEFAULT now(),
        last_active_at  timestamptz,
        started_at      timestamptz,
        stopped_at      timestamptz
      )
    `)
    await this.pool.query('CREATE INDEX IF NOT EXISTS idx_nb_tenants_state ON tenants (state)')
  }

  async byUser(userId) {
    const { rows } = await this.pool.query(`SELECT ${COLUMNS} FROM tenants WHERE user_id = $1`, [userId])
    return rows[0] ?? null
  }

  async byId(id) {
    const { rows } = await this.pool.query(`SELECT ${COLUMNS} FROM tenants WHERE id = $1`, [id])
    return rows[0] ?? null
  }

  async list() {
    const { rows } = await this.pool.query(
      `SELECT ${COLUMNS.split(',').map(c => c.trim().startsWith('(') ? c : `t.${c.trim()}`).join(', ')}, u.email
         FROM tenants t JOIN users u ON u.id = t.user_id
        ORDER BY t.last_active_at DESC NULLS LAST, t.created_at`,
    )
    return rows
  }

  async count() {
    const { rows } = await this.pool.query("SELECT count(*)::int AS count FROM tenants WHERE kind = 'managed'")
    return rows[0]?.count ?? 0
  }

  async secret(id) {
    const { rows } = await this.pool.query('SELECT provider_secret FROM tenants WHERE id = $1', [id])
    return rows[0]?.provider_secret ?? null
  }

  async update(id, fields) {
    const keys = Object.keys(fields)
    if (!keys.length) return this.byId(id)
    const sets = keys.map((key, index) => `${key} = $${index + 2}`).join(', ')
    const { rows } = await this.pool.query(`UPDATE tenants SET ${sets} WHERE id = $1 RETURNING ${COLUMNS}`, [id, ...keys.map(k => fields[k])])
    return rows[0] ?? null
  }

  async remove(id) {
    await this.pool.query('DELETE FROM tenants WHERE id = $1', [id])
  }

  // Allocates the tenant row and a free loopback port in one transaction,
  // under an advisory lock so two portals never hand out the same port.
  async createManaged({ userId, prefix, portBase, portCount, bindHost, maxTotal }) {
    const client = await this.pool.connect()
    try {
      await client.query('BEGIN')
      await client.query("SELECT pg_advisory_xact_lock(hashtext('nova-bots-tenants'))")
      const existing = await client.query(`SELECT ${COLUMNS} FROM tenants WHERE user_id = $1`, [userId])
      if (existing.rows[0]) {
        await client.query('COMMIT')
        return existing.rows[0]
      }
      const total = await client.query("SELECT count(*)::int AS count FROM tenants WHERE kind = 'managed'")
      if ((total.rows[0]?.count ?? 0) >= maxTotal) throw Object.assign(new Error('tenant limit reached'), { code: 'TENANT_LIMIT' })
      const used = new Set((await client.query('SELECT port FROM tenants WHERE port IS NOT NULL')).rows.map(row => row.port))
      let port = null
      for (let candidate = portBase; candidate < portBase + portCount; candidate += 1) {
        if (used.has(candidate)) continue
        if (await portFree(candidate, bindHost)) {
          port = candidate
          break
        }
      }
      if (!port) throw Object.assign(new Error('no free tenant port'), { code: 'TENANT_LIMIT' })
      const id = (await client.query('SELECT gen_random_uuid() AS id')).rows[0].id
      const { rows } = await client.query(
        `INSERT INTO tenants (id, user_id, kind, container, volume, port, state)
         VALUES ($1, $2, 'managed', $3, $4, $5, 'new') RETURNING ${COLUMNS}`,
        [id, userId, `${prefix}${id}`, `${prefix}${id}-data`, port],
      )
      await client.query('COMMIT')
      return rows[0]
    } catch (error) {
      await client.query('ROLLBACK').catch(() => {})
      throw error
    } finally {
      client.release()
    }
  }

  async createLegacy({ userId, container }) {
    const { rows } = await this.pool.query(
      `INSERT INTO tenants (user_id, kind, container, state) VALUES ($1, 'legacy', $2, 'running')
       ON CONFLICT (user_id) DO NOTHING RETURNING ${COLUMNS}`,
      [userId, container],
    )
    return rows[0] ?? this.byUser(userId)
  }

  async legacy() {
    const { rows } = await this.pool.query(`SELECT ${COLUMNS} FROM tenants WHERE kind = 'legacy' LIMIT 1`)
    return rows[0] ?? null
  }
}

// ---- the provisioner ---------------------------------------------------------

export class CapacityError extends Error {
  constructor(message = 'All workspaces are busy right now.') {
    super(message)
    this.code = 'CAPACITY'
  }
}

export class Tenants {
  constructor({ pool, config = tenancyConfigFromEnv(), docker, jar, audit = async () => {}, legacyToken, log = console }) {
    this.config = config
    this.store = new TenantStore(pool)
    this.pool = pool
    this.docker = docker ?? new DockerCli({ bin: config.docker })
    this.jar = jar
    this.audit = audit
    this.legacyToken = legacyToken
    this.log = log
    this.box = secretBox(config.secretKey)
    this.inflight = new Map()
    this.tokens = new Map()
    this.activity = new Map()
    this.sockets = new Map()
    this.timer = null
  }

  async migrate() {
    await this.store.migrate()
  }

  // The admin keeps the existing engine. NOVA_LEGACY_TENANT_EMAIL names the
  // account; without it, the oldest admin.
  async mapLegacy() {
    const current = await this.store.legacy()
    if (current) return current
    const { rows } = this.config.legacyEmail
      ? await this.pool.query('SELECT id, email FROM users WHERE lower(email) = $1', [this.config.legacyEmail])
      : await this.pool.query("SELECT id, email FROM users WHERE system_role = 'admin' ORDER BY created_at LIMIT 1")
    const owner = rows[0]
    if (!owner) return null
    if (await this.store.byUser(owner.id)) return null
    const tenant = await this.store.createLegacy({ userId: owner.id, container: this.config.legacyContainer })
    await this.audit({ action: 'tenant-map-legacy', actor: 'system', target: owner.email, detail: { tenant_id: tenant?.id, container: this.config.legacyContainer } })
    return tenant
  }

  // A tenant row (and its port) for an account. The container is created on
  // first access.
  async ensureRow(user) {
    const existing = await this.store.byUser(user.id)
    if (existing) return existing
    const tenant = await this.store.createManaged({
      userId: user.id,
      prefix: this.config.prefix,
      portBase: this.config.portBase,
      portCount: this.config.portCount,
      bindHost: this.config.bindHost,
      maxTotal: this.config.maxTotal,
    })
    await this.audit({ action: 'tenant-allocate', actor: 'system', target: user.email, detail: { tenant_id: tenant.id, port: tenant.port } })
    return tenant
  }

  // Every existing account gets a tenant row — never the shared engine — and
  // the admin keeps the shared engine. With provision=true the containers and
  // volumes are created too (not started).
  async backfill({ provision = false } = {}) {
    const legacy = await this.mapLegacy()
    const { rows } = await this.pool.query('SELECT id, email FROM users WHERE NOT is_forbidden ORDER BY created_at')
    const result = { legacy: legacy?.id ?? null, created: [], existing: [], provisioned: [], failed: [] }
    for (const user of rows) {
      const before = await this.store.byUser(user.id)
      try {
        const tenant = before ?? await this.ensureRow(user)
        ;(before ? result.existing : result.created).push({ email: user.email, tenant: tenant.id, kind: tenant.kind })
        if (provision && tenant.kind === 'managed') {
          await this.provision(tenant)
          result.provisioned.push(tenant.id)
        }
      } catch (error) {
        result.failed.push({ email: user.email, error: error.message })
      }
    }
    await this.audit({ action: 'tenant-backfill', actor: 'system', detail: { created: result.created.length, provisioned: result.provisioned.length, failed: result.failed.length } })
    return result
  }

  async provision(tenant) {
    const state = await this.docker.inspect(tenant.container)
    if (state.exists) return state
    await this.docker.ensureNetwork({ name: this.config.network, bridgeName: this.config.bridgeName, instance: this.config.instance })
    const labels = { 'nova-bots.instance': this.config.instance, 'nova-bots.tenant': tenant.id }
    await this.docker.ensureVolume(tenant.volume, labels)
    await this.docker.ensureVolume(`${tenant.volume}-work`, labels)
    // A provider key, when one is assigned, goes in through an env file that
    // exists only for the create call: never on a command line, never in a log.
    let dir = null
    let envFile = null
    try {
      const sealed = await this.store.secret(tenant.id)
      if (sealed) {
        if (!this.box) throw new Error('a provider key is assigned but NOVA_TENANT_SECRET_KEY is not set')
        const values = this.box.open(sealed)
        dir = await mkdtemp(join(tmpdir(), 'nova-tenant-'))
        envFile = join(dir, 'env')
        const lines = Object.entries(values)
          .filter(([key, value]) => this.config.keyEnvs.includes(key) && !/[\r\n]/.test(String(value)))
          .map(([key, value]) => `${key}=${value}`)
        await writeFile(envFile, `${lines.join('\n')}\n`, { mode: 0o600 })
      }
      await this.docker.run(containerArgs({ tenant, config: this.config, envFile }))
    } finally {
      if (dir) await rm(dir, { recursive: true, force: true })
    }
    await this.audit({ action: 'tenant-provision', actor: 'system', target: tenant.id, detail: { container: tenant.container, port: tenant.port } })
    return this.docker.inspect(tenant.container)
  }

  async runningManaged() {
    const { rows } = await this.pool.query("SELECT id FROM tenants WHERE kind = 'managed' AND state = 'running'")
    return rows.map(row => row.id)
  }

  // Before a start: free a slot when the hard cap is reached, by stopping the
  // least recently active running tenant that has no open live feed.
  async makeRoom(exceptId) {
    const running = (await this.runningManaged()).filter(id => id !== exceptId)
    if (running.length < this.config.maxRunning) return
    const candidates = running
      .filter(id => !(this.sockets.get(id)?.size))
      .sort((a, b) => (this.activity.get(a) ?? 0) - (this.activity.get(b) ?? 0))
    if (!candidates.length) throw new CapacityError()
    const victim = await this.store.byId(candidates[0])
    await this.stop(victim, { reason: 'capacity' })
  }

  // Lazy start: create when missing, start when stopped, then wait until the
  // engine mints a cookie from its own fresh launch token. Single flight per
  // tenant, so concurrent requests share one start.
  ensureRunning(tenant) {
    if (tenant.kind === 'legacy') return Promise.resolve(tenant)
    const pending = this.inflight.get(tenant.id)
    if (pending) return pending
    const work = (async () => {
      let state = await this.docker.inspect(tenant.container)
      if (state.running) {
        if (tenant.state !== 'running') tenant = await this.store.update(tenant.id, { state: 'running' })
        return tenant
      }
      await this.makeRoom(tenant.id)
      if (!state.exists) state = await this.provision(tenant)
      this.forget(tenant.id)
      await this.docker.run(['start', tenant.container])
      await this.waitReady(tenant)
      this.activity.set(tenant.id, Date.now())
      const updated = await this.store.update(tenant.id, { state: 'running', started_at: new Date(), last_active_at: new Date(), last_error: null })
      await this.audit({ action: 'tenant-start', actor: 'system', target: tenant.id, detail: { container: tenant.container } })
      return updated
    })().catch(async error => {
      if (error.code !== 'CAPACITY') await this.store.update(tenant.id, { state: 'error', last_error: String(error.message).slice(0, 500) }).catch(() => {})
      throw error
    }).finally(() => this.inflight.delete(tenant.id))
    this.inflight.set(tenant.id, work)
    return work
  }

  async waitReady(tenant) {
    const deadline = Date.now() + this.config.startTimeoutMs
    const url = this.engineUrl(tenant)
    while (Date.now() < deadline) {
      try {
        const cookie = await this.jar.get({ key: tenant.id, url, host: 'localhost', token: () => this.tokenFor(tenant, { fresh: true }), fresh: true })
        if (cookie) return
      } catch { /* not up yet */ }
      const state = await this.docker.inspect(tenant.container)
      if (!state.running) throw new Error('the tenant engine exited during start')
      await new Promise(resolve => setTimeout(resolve, 750))
    }
    throw new Error('the tenant engine did not become ready in time')
  }

  engineUrl(tenant) {
    if (tenant.kind === 'legacy') return this.config.legacyUrl
    return `http://${this.config.bindHost === '0.0.0.0' ? '127.0.0.1' : this.config.bindHost}:${tenant.port}`
  }

  // The launch token lives in the tenant's own volume; it is read through the
  // container and kept in memory only.
  async tokenFor(tenant, { fresh = false } = {}) {
    if (tenant.kind === 'legacy') return this.legacyToken()
    if (!fresh && this.tokens.has(tenant.id)) return this.tokens.get(tenant.id)
    try {
      const token = await this.docker.readFile(tenant.container, '/data/.launch-token')
      if (token) this.tokens.set(tenant.id, token)
      return token || null
    } catch {
      return null
    }
  }

  forget(id) {
    this.tokens.delete(id)
    this.jar.invalidate(id)
  }

  // The bridge target for one account: its own engine and nothing else.
  async targetFor(user) {
    let tenant = await this.store.byUser(user.id)
    if (!tenant) tenant = await this.ensureRow(user)
    tenant = await this.ensureRunning(tenant)
    this.touch(tenant.id)
    const url = this.engineUrl(tenant)
    return {
      key: tenant.id,
      tenantId: tenant.id,
      url,
      cookie: (host, { fresh = false } = {}) => this.jar.get({ key: tenant.id, url, host, fresh, token: () => this.tokenFor(tenant, { fresh }) }),
      invalidate: () => this.forget(tenant.id),
    }
  }

  touch(id) {
    this.activity.set(id, Date.now())
  }

  socketOpened(id, socket) {
    if (!this.sockets.has(id)) this.sockets.set(id, new Set())
    this.sockets.get(id).add(socket)
    this.touch(id)
  }

  socketClosed(id, socket) {
    this.sockets.get(id)?.delete(socket)
    this.touch(id)
  }

  closeSockets(id) {
    for (const socket of this.sockets.get(id) ?? []) socket.destroy()
    this.sockets.delete(id)
  }

  async stop(tenant, { reason = 'admin', actor = 'system' } = {}) {
    if (!tenant) return null
    if (tenant.kind === 'legacy') throw new Error('the shared engine is not managed by the provisioner')
    this.closeSockets(tenant.id)
    const state = await this.docker.inspect(tenant.container)
    if (state.running) await this.docker.run(['stop', '--time', '15', tenant.container], { timeout: 60000 })
    this.forget(tenant.id)
    await this.audit({ action: 'tenant-stop', actor, target: tenant.id, detail: { reason } })
    return this.store.update(tenant.id, { state: state.exists ? 'stopped' : 'new', stopped_at: new Date() })
  }

  async start(tenant, { actor = 'system' } = {}) {
    if (tenant.kind === 'legacy') throw new Error('the shared engine is not managed by the provisioner')
    const result = await this.ensureRunning(tenant)
    await this.audit({ action: 'tenant-start-request', actor, target: tenant.id, detail: {} })
    return result
  }

  // Removes the tenant: container, both volumes, row. With exportTo, both
  // volumes are first archived to a tarball in that host folder.
  async remove(tenant, { exportData = false, actor = 'system' } = {}) {
    if (tenant.kind === 'legacy') {
      await this.store.remove(tenant.id)
      await this.audit({ action: 'tenant-unmap-legacy', actor, target: tenant.id, detail: {} })
      return { removed: true, exported: null }
    }
    this.closeSockets(tenant.id)
    let exported = null
    const state = await this.docker.inspect(tenant.container)
    if (state.running) await this.docker.run(['stop', '--time', '15', tenant.container], { timeout: 60000 })
    if (exportData) {
      if (!this.config.exportDir) throw new Error('NOVA_TENANT_EXPORT_DIR is not set')
      const file = `${tenant.id}-${new Date().toISOString().replace(/[:.]/g, '-')}.tar.gz`
      const uid = typeof process.getuid === 'function' ? process.getuid() : 1000
      const gid = typeof process.getgid === 'function' ? process.getgid() : 1000
      await this.docker.run([
        'run', '--rm', '--network', 'none', '--user', `${uid}:${gid}`, '--entrypoint', 'tar',
        '--volume', `${tenant.volume}:/export/data:ro`, '--volume', `${tenant.volume}-work:/export/workspace:ro`,
        '--volume', `${this.config.exportDir}:/out`,
        this.config.image, 'czf', `/out/${file}`, '-C', '/export', 'data', 'workspace',
      ], { timeout: 600000 })
      exported = join(this.config.exportDir, file)
    }
    if (state.exists) await this.docker.run(['rm', '-f', tenant.container])
    for (const volume of [tenant.volume, `${tenant.volume}-work`]) {
      await this.docker.run(['volume', 'rm', '-f', volume]).catch(() => {})
    }
    this.forget(tenant.id)
    this.activity.delete(tenant.id)
    await this.store.remove(tenant.id)
    await this.audit({ action: 'tenant-delete', actor, target: tenant.id, detail: { exported: Boolean(exported) } })
    return { removed: true, exported }
  }

  // Assigns (or clears) a provider key for ONE tenant. The container is
  // recreated so the key reaches its env; the volumes are kept.
  async assignKey(tenant, values, { actor = 'admin' } = {}) {
    if (tenant.kind === 'legacy') throw new Error('the shared engine takes its keys from docker/.env')
    let sealed = null
    if (values) {
      if (!this.box) throw new Error('NOVA_TENANT_SECRET_KEY is not set (32+ characters)')
      const names = Object.keys(values)
      if (!names.length) throw new Error('no key given')
      for (const name of names) {
        if (!this.config.keyEnvs.includes(name)) throw new Error(`${name} is not an assignable key (NOVA_TENANT_KEY_ENVS)`)
        if (typeof values[name] !== 'string' || !values[name] || /[\r\n]/.test(values[name])) throw new Error(`${name} must be a one-line string`)
      }
      sealed = this.box.seal(values)
    }
    await this.store.update(tenant.id, { provider_secret: sealed })
    await this.recreate(tenant, { actor, reason: values ? 'key-assigned' : 'key-cleared' })
    await this.audit({ action: values ? 'tenant-key-assign' : 'tenant-key-clear', actor, target: tenant.id, detail: { envs: values ? Object.keys(values) : [] } })
    return this.store.byId(tenant.id)
  }

  async setLimits(tenant, limits, { actor = 'admin' } = {}) {
    const clean = {}
    if (limits.cpus !== undefined) clean.cpus = String(Number(limits.cpus))
    if (limits.memory !== undefined) {
      if (!/^\d+[kmg]$/i.test(String(limits.memory))) throw new Error('memory must look like 1536m or 2g')
      clean.memory = String(limits.memory)
    }
    if (limits.pids !== undefined) clean.pids = Math.max(64, Math.floor(Number(limits.pids)))
    await this.store.update(tenant.id, { limits: JSON.stringify(clean) })
    await this.recreate(tenant, { actor, reason: 'limits' })
    await this.audit({ action: 'tenant-limits', actor, target: tenant.id, detail: clean })
    return this.store.byId(tenant.id)
  }

  async recreate(tenant, { actor, reason }) {
    const fresh = await this.store.byId(tenant.id)
    const state = await this.docker.inspect(fresh.container)
    if (!state.exists) return
    this.closeSockets(fresh.id)
    await this.docker.run(['rm', '-f', fresh.container])
    this.forget(fresh.id)
    await this.store.update(fresh.id, { state: 'new' })
    await this.provision(fresh)
    if (state.running) await this.ensureRunning(await this.store.byId(fresh.id))
    await this.audit({ action: 'tenant-recreate', actor, target: fresh.id, detail: { reason } })
  }

  // Brings the table in line with docker (after a portal or host restart).
  async reconcile() {
    const containers = await this.docker.listLabelled(this.config.instance)
    const byName = new Map(containers.map(c => [c.name, c]))
    const tenants = await this.store.list()
    for (const tenant of tenants) {
      if (tenant.kind !== 'managed') continue
      const container = byName.get(tenant.container)
      const state = container ? (container.running ? 'running' : 'stopped') : 'new'
      if (state !== tenant.state && tenant.state !== 'error') await this.store.update(tenant.id, { state })
      if (state === 'running' && !this.activity.has(tenant.id)) {
        this.activity.set(tenant.id, tenant.last_active_at ? new Date(tenant.last_active_at).getTime() : Date.now())
      }
    }
    const known = new Set(tenants.map(t => t.container))
    return { orphans: containers.filter(c => !known.has(c.name)).map(c => c.name) }
  }

  // Idle stop: a running tenant with no open live feed and no request for
  // idleMinutes is stopped; its data stays in its volumes.
  async reap(now = Date.now()) {
    const idleMs = this.config.idleMinutes * 60000
    const stopped = []
    for (const id of await this.runningManaged()) {
      if (this.inflight.has(id) || this.sockets.get(id)?.size) continue
      const last = this.activity.get(id)
      if (last === undefined) {
        this.activity.set(id, now)
        continue
      }
      if (now - last >= idleMs) {
        try {
          await this.stop(await this.store.byId(id), { reason: 'idle' })
          stopped.push(id)
        } catch (error) {
          this.log.error(`tenants: idle stop of ${id} failed: ${error.message}`)
        }
      } else {
        await this.store.update(id, { last_active_at: new Date(last) }).catch(() => {})
      }
    }
    return stopped
  }

  startReaper() {
    if (this.timer) return
    this.timer = setInterval(() => {
      this.reap().catch(error => this.log.error(`tenants: reaper failed: ${error.message}`))
    }, this.config.reapIntervalMs)
    this.timer.unref?.()
  }

  stopReaper() {
    if (this.timer) clearInterval(this.timer)
    this.timer = null
  }

  async usage() {
    const tenants = await this.store.list()
    const running = tenants.filter(t => t.kind === 'managed' && t.state === 'running').map(t => t.container)
    const stats = await this.docker.stats(running).catch(() => ({}))
    return tenants.map(tenant => ({
      id: tenant.id,
      email: tenant.email,
      kind: tenant.kind,
      state: tenant.state,
      container: tenant.container,
      port: tenant.port,
      has_key: tenant.has_key,
      limits: { ...this.config.limits, ...(tenant.limits ?? {}) },
      live_sockets: this.sockets.get(tenant.id)?.size ?? 0,
      last_active_at: this.activity.has(tenant.id) ? new Date(this.activity.get(tenant.id)).toISOString() : tenant.last_active_at,
      created_at: tenant.created_at,
      started_at: tenant.started_at,
      stopped_at: tenant.stopped_at,
      last_error: tenant.last_error,
      usage: stats[tenant.container] ?? null,
    }))
  }
}
